LUAI_DDEF const char *const luaT_typenames_[LUA_TOTALTYPES] = {

  "no value",

  "nil", "boolean", udatatypename, "number",

  "string", "table", "function", udatatypename, "thread",

  "upvalue", "proto" /* these last cases are used for tests only */

